int moveFloor(int currentFloor, char moveCode) {
    if (moveCode == '(')
        return currentFloor + 1;
    else // if (moveCode == ')')
        return currentFloor - 1;
}

int solvePart1(const char *moves, int numMoves) {
    int current = INIT_FLOOR;
    for (int i = 0; i < numMoves; i++)
       current = moveFloor(current, moves[i]);
    return current;
}

int solvePart2(const char *moves, int numMoves) {
    int current = INIT_FLOOR;
    int movesTaken = 1;
    for (int i = 0; i < numMoves; i++, movesTaken++) {
        current = moveFloor(current, moves[i]);
        if (current == BASEMENT)
            break;
    }

    return movesTaken;
}

void solveBothParts(const char *moves, int numMoves, int *finalFloor, int *movesToReachBasement) {
    int current = INIT_FLOOR;
    int movesTaken = 0;
    int i = 0;
    for (; i < numMoves; i++) {
        movesTaken++;
        current = moveFloor(current, moves[i]);
        if (current == BASEMENT)
            break;
    }
    *movesToReachBasement = movesTaken;
    i++;
    for (; i < numMoves; i++)
        current = moveFloor(current, moves[i]);
    *finalFloor = current;
}

int main()
{
    const char* inputData = PROBLEM_DATA;
                         // PART1_TEST_DATA1;
                         // PART1_TEST_DATA2;
                         // PART1_TEST_DATA3;
                         // PART2_TEST_DATA1;
                         // PART2_TEST_DATA2;

    int numMoves = strlen(inputData);
    int finalFloor, movesToReachBasement;

    clock_t startTimePart1 = clock();

    finalFloor = solvePart1(inputData, numMoves);
    printf("After %d moves the floor Santa Claus arrives to is: %d\n", 
        numMoves, finalFloor);
    
    clock_t endTimePart1 = clock();
    clock_t startTimePart2 = clock();

    movesToReachBasement = solvePart2(inputData, numMoves);
    printf("The position of the character that causes Santa to first enter the basement is: %d\n",
        movesToReachBasement);

    clock_t endTimePart2 = clock();
    clock_t startTimeBothParts = clock();

    solveBothParts(inputData, numMoves, &finalFloor, &movesToReachBasement);

    clock_t endTimeBothParts = clock();
    
    return 0;
}
    